// src/lib/mcp/tools/search-products.ts
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z3 } from "npm:zod@^3.25.76";
import { allCategories as mizzouCategories2 } from "npm:@/data/mizzouCategoryData";
import { allCategories as indianaCategories2 } from "npm:@/data/indianaCategoryData";
import { allCategories as butlerCategories2 } from "npm:@/data/butlerCategoryData";
var bySchool2 = {
  missouri: mizzouCategories2,
  mizzou: mizzouCategories2,
  indiana: indianaCategories2,
  butler: butlerCategories2
};
var search_products_default = defineTool3({
  name: "search_products",
  title: "Search products",
  description: "Search products in a FanPact storefront by keyword. Optionally filter by category slug. Returns up to 25 matches with NIL contribution amounts.",
  inputSchema: {
    school: z3.enum(["missouri", "mizzou", "indiana", "butler"]).describe("Storefront to search."),
    query: z3.string().describe("Keyword to match against product name or brand."),
    category: z3.string().optional().describe("Optional category slug to restrict the search.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ school, query, category }) => {
    const cats = bySchool2[school];
    const q = query.trim().toLowerCase();
    const pool = category ? cats.filter((c) => c.slug === category) : cats;
    const matches = [];
    for (const c of pool) {
      for (const p of c.products) {
        if (p.name.toLowerCase().includes(q) || p.brand.toLowerCase().includes(q)) {
          matches.push({
            id: p.id,
            name: p.name,
            brand: p.brand,
            isNameBrand: p.isNameBrand,
            price: p.price,
            nilContribution: p.nilDonation,
            rating: p.rating,
            reviews: p.reviews,
            category: c.slug,
            subcategory: p.subcategory
          });
          if (matches.length >= 25) break;
        }
      }
      if (matches.length >= 25) break;
    }
    return {
      content: [{ type: "text", text: JSON.stringify(matches, null, 2) }],
      structuredContent: { school, query, count: matches.length, products: matches }
    };
  }
});

// src/lib/mcp/tools/get-roster.ts
import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z4 } from "npm:zod@^3.25.76";
import { sportRosters } from "npm:@/data/sportsRosters";
var get_roster_default = defineTool4({
  name: "get_roster",
  title: "Get sport roster",
  description: "Get the Missouri Tigers athlete roster for a given sport (e.g. football, mens-basketball, womens-basketball, baseball, softball, soccer, volleyball).",
  inputSchema: {
    sport: z4.string().describe("Sport slug, e.g. 'football' or 'volleyball'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ sport }) => {
    const key = sport.toLowerCase();
    const roster = sportRosters[key];
    if (!roster) {
      const available = Object.keys(sportRosters);
      return {
        content: [
          { type: "text", text: `No roster for '${sport}'. Available: ${available.join(", ")}` }
        ],
        isError: true
      };
    }
    return {
      content: [{ type: "text", text: JSON.stringify(roster, null, 2) }],
      structuredContent: { sport: key, count: roster.length, players: roster }
    };
  }
});

